head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";      // [부모 data] 업무처리번호 (AS-IS parentWin.scwin.vBzProcsNo)
scwin.RT_DECIMAL = 6;      // 보수·비용 소수 자리(원본 maxdecimalplace 6)
scwin.isSaved = false;      // 저장·수정 성공 여부 — X 로 닫히면 부모가 isCloseButtonClick 으로 판정한다(부모 09303 은 원본대로 재조회하지 않음)

// 원본 : /pf/ULDSTF09320.gfm (상장형 수익증권 상품정보관리 팝업) — W-Craft 1차 변환 + API 적용 개발 사본(ui/ULDSTF09320/ULDSTF09320.xml)
/*
 * 화면 동작
 *  - 부모(ULDSTF09303 신규상장관리)가 넘긴 업무처리번호로 상품정보를 조회한다. 등록된 정보가 없으면 [저장], 있으면 [수정]만 켠다.
 *  - 보수 4종을 넣고 [계산] → 총보수, 총보수 + 기타비용 + 스왑비용 → 총비용. 저장·수정 전에 계산값과 일치하는지 확인한다.
 *  - 통신은 화면에 적용된 API(경로·method·keyInfo)를 명세로 간주한다(사용자 결정 2026-10-29 준용).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09320/ULDSTF09320.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 파라미터 수신 → 종목 표시 → 상품정보 조회 → 등록 여부로 [저장]/[수정] 상태. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 파라미터 수신 — 원본 parentWin.scwin.vBzProcsNo·txb_SearchIsuCd·txb_SearchIsuNm (§1.2)
    const param = $c.data.getParameter() ?? {};
    scwin.vBzProcsNo = String(param.bzProcsNo ?? "");
    txb_ISU_CD.setValue(String(param.isuCd ?? ""));
    txb_ISU_NM.setValue(String(param.isuNm ?? ""));

    // 2) 상품정보 조회 → 등록 여부로 버튼 상태
    await scwin.selectOne();
    scwin.applyButtonState();
    edt_CIS_COST_RT.focus();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_calcul_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 계산 클릭 — 총보수·총비용을 합산해 채운다. (원본 btn_calcul_onclick → fn_calcul — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_calcul_onclick = async function (e) {
    try {
        await scwin.calculate();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_calcul_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 클릭 — 상품정보를 등록한다. (원본 btn_save_onclick → fn_save — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_save_onclick = async function (e) {
    try {
        await scwin.save("I");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 클릭 — 상품정보를 수정한다. (원본 btn_Update_onclick → fn_update — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.save("U");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09320.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.txa_PF_INVSTWARN_CONTN_onblur
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상품정보(투자유의사항)를 벗어나면 첫 보수 칸으로 포커스를 돌린다 — 원본은 비활성인 총보수로 보내 동작하지 않았다.
 * (원본 txa_PF_INVSTWARN_CONTN_OnKillFocus — §4, §8 #6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.txa_PF_INVSTWARN_CONTN_onblur = function (e) {
    try {
        edt_CIS_COST_RT.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09320.txa_PF_INVSTWARN_CONTN_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상품정보 조회. 등록 전이면 응답 body 가 비어 올 수 있어 target 대신 body 가 객체일 때만 적재하고, 아니면 비운다. (원본 fn_read_sync — §5.1)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectOne = async function () {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/pf/new-listing/prod-info/select-one",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.vBzProcsNo });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    const body = result.responseJSON.body;
    if (body !== null && typeof body === "object") {
        dma_itemRes.setJSON(body);
    } else {
        dma_itemRes.setEmptyValue();
    }
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상품정보 등록(I)·수정(U) 전송. (원본 fn_trs + trs_Save_OnSuccess — §5.2·§5.3)
 * @param {String} trJob 처리구분 I: 등록, U: 수정
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const sbmOptions = {
        id : (trJob === "I") ? "sbm_prodInfoInsert" : "sbm_prodInfoUpdate",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/pf/new-listing/prod-info/register" : "/api/listing/lstproc/pf/new-listing/prod-info/modify",
        ref : "dma_itemRes",
        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    return await scwin.checkResult(result, (trJob === "I") ? "저장" : "수정");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 여부로 버튼 상태 — 등록 전이면 [저장]만, 등록됐으면 [수정]만 켠다. (원본 scwin.init 분기 — §6.1)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    const registered = !$c.util.isEmpty(dma_itemRes.get("bzProcsNo"));
    btn_save.setDisabled(registered);
    btn_Update.setDisabled(!registered);
};

/**
 * @method
 * @name scwin.toRate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보수·비용 칸의 값을 숫자로 — 빈 값은 0. (원본 parseFloat 합산 — §6.2)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Number} 숫자 값
 * @hidden N
 */
scwin.toRate = function (comp) {
    const value = Number.parseFloat(comp.getValue());
    return Number.isNaN(value) ? 0 : value;
};

/**
 * @method
 * @name scwin.checkRate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 보수·비용 6칸 필수 입력 확인. 원본은 결과를 버려 빈 칸이 있어도 계산·저장이 계속됐다 — 결과로 멈춘다. (원본 fn_checkRt — §6.2, §8 #2)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkRate = async function () {
    const items = [
        [edt_CIS_COST_RT, "'집합투자업자보수'를 입력하세요."],
        [edt_AP_CMP_LP_COST_RT, "'AP/LP보수'를 입력하세요."],
        [edt_TRST_COM_COST_RT, "'신탁회사보수'를 입력하세요."],
        [edt_TRANSAGNT_COST_RT, "'일반사무관리회사보수'를 입력하세요."],
        [edt_MISC_COST_RT, "'기타비용'을 입력하세요."],
        [edt_SYNTH_SWAP_COST_RT, "'스왑비용'을 입력하세요."]
    ];
    for (const [comp, msg] of items) {
        if ($c.util.isEmpty(comp.getValue())) {
            await $c.win.alert(msg);
            comp.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name scwin.getTotals
 * @author Inswave
 * @date 2026. 10. 30
 * @description 총보수 = 보수 4종 합, 총비용 = 총보수 + 기타비용 + 스왑비용 — 소수 6자리로 반올림한 숫자. (원본 fn_calcul·fn_CheckForm 의 toFixed(6) — §6.2)
 * @returns {Object} { totFee, totCost }
 * @hidden N
 */
scwin.getTotals = function () {
    const totFee = Number((scwin.toRate(edt_CIS_COST_RT) + scwin.toRate(edt_AP_CMP_LP_COST_RT)
        + scwin.toRate(edt_TRST_COM_COST_RT) + scwin.toRate(edt_TRANSAGNT_COST_RT)).toFixed(scwin.RT_DECIMAL));
    const totCost = Number((totFee + scwin.toRate(edt_MISC_COST_RT) + scwin.toRate(edt_SYNTH_SWAP_COST_RT)).toFixed(scwin.RT_DECIMAL));
    return { totFee : totFee, totCost : totCost };
};

/**
 * @method
 * @name scwin.calculate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 계산 — 필수 칸이 다 있으면 총보수·총비용을 채운다. (원본 fn_calcul — §6.2)
 * @returns
 * @hidden N
 */
scwin.calculate = async function () {
    if (!await scwin.checkRate()) return;

    const totals = scwin.getTotals();
    edt_PF_TOT_FEE.setValue(totals.totFee);
    edt_TOT_COST_RT.setValue(totals.totCost);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 검사 — 필수 보수·비용, 총보수·총비용이 계산값과 같은지(숫자로 비교), 상세내역·홈페이지·회계기간·분배금 지급기준일·
 * 상품정보(기본정보·투자유의사항)의 필수·최대 byte. 원본은 문자열로 비교해 표시 형식에 따라 늘 다르다고 볼 수 있었다. (원본 fn_CheckForm — §6.3, §8 #3)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (!await scwin.checkRate()) return false;

    const totals = scwin.getTotals();
    if (scwin.toRate(edt_PF_TOT_FEE) !== totals.totFee) {
        await $c.win.alert("입력한 보수값과 현재 '총보수'값이 일치하지 않습니다.\n[계산]버튼을 눌러 합산하세요.");
        return false;
    }
    if (scwin.toRate(edt_TOT_COST_RT) !== totals.totCost) {
        await $c.win.alert("입력한 보수값과 현재 '총비용'값이 일치하지 않습니다.\n[계산]버튼을 눌러 합산하세요.");
        return false;
    }

    // 선택 입력 — 값이 있을 때만 최대 byte
    if (!$c.util.isEmpty(txa_MISC_COST_DTL.getValue()) && !$c.stf.checkMaxLength(txa_MISC_COST_DTL, 200, "기타비용 상세내역")) return false;
    if (!$c.util.isEmpty(txa_SYNTH_COST_DTL.getValue()) && !$c.stf.checkMaxLength(txa_SYNTH_COST_DTL, 200, "스왑비용 상세내역")) return false;

    // 필수 입력 + 최대 byte
    const required = [
        [txb_HPAGE, "홈페이지", 200],
        [txb_TRST_CALC_PD_CONTN, "회계기간", 200],
        [txb_TRST_DISTR_PAY_BAS_DD_CONTN, "분배금 지급기준일", 300],
        [txa_PF_PROD_INFO, "상품정보(기본정보)", 4000],
        [txa_PF_INVSTWARN_CONTN, "상품정보(투자유의사항)", 4000]
    ];
    for (const [comp, title, maxByte] of required) {
        if ($c.util.isEmpty(comp.getValue())) {
            await $c.win.alert("[" + title + "]를 입력하세요.");
            comp.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(comp, maxByte, title)) return false;    // 안내·포커스는 공통 함수
    }
    return true;
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 30
 * @description 처리 결과 판정 — 통신 성공이고 completeYn 이 false 가 아니면 성공. register·modify 는 응답 정의가 없어 completeYn 이 없으면 success 만 본다. (§5.2)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    // TODO: 등록·수정 응답 구조 확인 필요 — completeYn 유무 (§10 #2)
    const completeYn = result.responseJSON?.body?.completeYn;
    const completed = (completeYn === undefined || completeYn === null || String(completeYn) === "true" || completeYn === "Y");
    if (result.responseJSON?.success === true && completed) return true;

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
    return false;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록(I)·수정(U) — 검사 → 확인 → 전송 → 안내. 등록이면 업무처리번호를 채워 보내고, 성공하면 [저장]을 잠그고 [수정]을 켠다
 * (원본은 [저장]만 잠가 다시 열 때까지 수정할 수 없었다). (원본 fn_save·fn_update·trs_Save_OnSuccess — §6.4, §8 #4)
 * @param {String} trJob 처리구분 I: 등록, U: 수정
 * @returns
 * @hidden N
 */
scwin.save = async function (trJob) {
    if (!await scwin.validate()) return;

    // "[저장]/[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(trJob)) return;

    if (trJob === "I") {
        dma_itemRes.set("bzProcsNo", scwin.vBzProcsNo);
    }
    if (!await scwin.saveTrs(trJob)) return;

    scwin.isSaved = true;
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", (trJob === "I") ? "저장" : "수정"));
    scwin.applyButtonState();
};
